class HttpTransport:
    """Synchronous transport (one per client).

    Service options (all optional):

    * ``request_id_headers``: vendor request id headers, checked before
      :data:`REQUEST_ID_HEADERS`.
    * ``retry_after_headers``: headers read (in order) for the delay a 429/503 response asks
      for; default ``("retry-after",)``, e.g. ``("retry-after", "x-ratelimit-reset")``. See
      :func:`retry_after_from_headers`.
    * ``error_mapper``: ``mapper(error, response)`` returns a service-specific error for an
      HTTP error response (or ``None`` to keep the default). The mapped error is what
      ``Hooks.on_error``, the retry planner (``retry_after``) and the caller see; whether a
      status is retried stays the SPEC rule. Exceptions raised by the mapper are logged and
      ignored.

    Every call after :meth:`close` raises :class:`CancelledError` ("client is closed").
    """

    def __init__(
        self,
        config: BaseConfig,
        *,
        known_secrets: Callable[[], list[str]] | None = None,
        http_transport: httpx.BaseTransport | None = None,
        clock: Callable[[], float] = time.monotonic,
        request_id_headers: Sequence[str] = (),
        retry_after_headers: Sequence[str] = RETRY_AFTER_HEADERS,
        error_mapper: ErrorMapper | None = None,
    ) -> None:
        self._core = _TransportCore(
            config,
            known_secrets=known_secrets,
            clock=clock,
            request_id_headers=request_id_headers,
            retry_after_headers=retry_after_headers,
            error_mapper=error_mapper,
        )
        self._closed = CancelToken()
        self._client = httpx.Client(
            trust_env=False,
            verify=self._core.verify,
            proxy=config.proxy,
            timeout=self._core.timeout,
            transport=http_transport,
            follow_redirects=False,
        )

    @property
    def log(self) -> SdkLogger:
        return self._core.log

    @property
    def closed(self) -> bool:
        return self._closed.cancelled

    def close(self) -> None:
        """Close the connection pool and abort backoff sleeps (idempotent)."""
        if self._closed.cancelled:
            return
        self._closed.cancel()
        self._client.close()

    def _send_once(
        self, req: Request, url: str, headers: dict[str, str], body: bytes | None, timeout: float
    ) -> Response:
        core = self._core
        attempt_deadline = core.clock() + timeout
        t = httpx.Timeout(
            connect=min(core.config.connect_timeout, timeout),
            read=timeout,
            write=timeout,
            pool=timeout,
        )
        with self._client.stream(
            req.method.upper(), url, headers=headers, content=body, timeout=t
        ) as r:
            chunks = []
            for chunk in r.iter_bytes():
                chunks.append(chunk)
                if core.clock() > attempt_deadline:
                    raise _AttemptTimeout
            return Response(
                r.status_code,
                r.headers,
                b"".join(chunks),
                request_id=core.request_id(r.headers),
                operation=req.op,
            )

    def _send_cancellable(
        self,
        req: Request,
        url: str,
        headers: dict[str, str],
        body: bytes | None,
        timeout: float,
        cancel: CancelToken,
    ) -> Response:
        done = threading.Event()
        box: dict[str, Any] = {}

        def run() -> None:
            try:
                box["value"] = self._send_once(req, url, headers, body, timeout)
            except BaseException as exc:  # noqa: BLE001 - re-raised in the caller thread
                box["error"] = exc
            finally:
                done.set()

        unregister = cancel.on_cancel(done.set)
        unregister_closed = self._closed.on_cancel(done.set)
        worker = threading.Thread(target=run, name="grow-http-attempt", daemon=True)
        worker.start()
        done.wait()
        unregister()
        unregister_closed()
        if "value" in box:
            return box["value"]  # type: ignore[no-any-return]
        if "error" in box:
            raise box["error"]
        if cancel.cancelled:
            raise CancelledError(f"{req.op}: cancelled")
        raise self._core.closed_error(req.op)

    def _sleep(self, delay: float, req: Request, cancel: CancelToken | None) -> None:
        wake = threading.Event()
        unregister_closed = self._closed.on_cancel(wake.set)
        unregister_cancel = cancel.on_cancel(wake.set) if cancel else None
        try:
            wake.wait(delay)
        finally:
            unregister_closed()
            if unregister_cancel:
                unregister_cancel()
        if cancel is not None and cancel.cancelled:
            raise CancelledError(f"{req.op}: cancelled")
        if self._closed.cancelled:
            raise self._core.closed_error(req.op)

    def request(self, req: Request, *, cancel: CancelToken | None = None) -> Response:
        """Send ``req`` with retries; return the response or raise the mapped error."""
        core = self._core
        if self._closed.cancelled:
            raise core.closed_error(req.op)
        url = core.url_for(req)
        headers = core.headers_for(req)
        body = core.body_for(req)
        request_timeout = req.timeout if req.timeout is not None else core.config.request_timeout
        deadline = core.clock() + core.config.total_timeout
